                  <p className="text-sm text-gray-600 mb-3">N° {quotation.quotationNumber}</p>

                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                    <div>
                      <span className="text-sm text-gray-600">Montant</span>
