import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { 
  Calendar,
  Download, 
  Eye, 
  File,
  FileText,
  Filter,
  Folder,
  FolderOpen,
  Image,
  Plus,
  Search,
  Upload
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { FadeIn } from '../../components/animations';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useToast } from '@/hooks/use-toast';

interface Document {
  id: string;
  name: string;
  type: 'contract' | 'plan' | 'permit' | 'invoice' | 'photo' | 'report' | 'other';
  category: string;
  projectId: string;
  projectName: string;
  size: number;
  uploadedDate: string;
  uploadedBy: string;
  url: string;
  description?: string;
  isPublic: boolean;
  version?: number;
}

interface Folder {
  id: string;
  name: string;
  projectId: string;
  projectName: string;
  documentCount: number;
  lastModified: string;
}

const mockFolders: Folder[] = [
  {
    id: '1',
    name: 'Villa Moderne Sidi Bou Said',
    projectId: '1',
    projectName: 'Villa Moderne Sidi Bou Said',
    documentCount: 12,
    lastModified: '2024-06-20'
  },
  {
    id: '2',
    name: 'Rénovation Appartement Tunis',
    projectId: '2',
    projectName: 'Rénovation Appartement Tunis',
    documentCount: 8,
    lastModified: '2024-06-25'
